def transform(grid):
    out=[row[:] for row in grid]; h,w=len(grid),len(grid[0])
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    for r,c in marks:
        if r==0 or r==h-1:
            for i in range(h): out[i][c]=1
        if c==0 or c==w-1:
            for j in range(w): out[r][j]=1
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          x,y=stack.pop(); comp.append((x,y))
          for a in range(max(0,x-1),min(h,x+2)):
            for b in range(max(0,y-1),min(w,y+2)):
              if grid[a][b]==2 and (a,b) not in seen: seen.add((a,b)); stack.append((a,b))
        if any(out[x][y]==1 for x,y in comp):
          for x,y in comp: out[x][y]=1
    return out
